import {salonDateParts} from './api.js';
import {availableSlots,durationMinutes,minutesOf,collisionFor,formatTime} from './scheduling.js';
export function createClientPortal(ctx){
 const {state,api,config,esc,icon,money,find,image,breed,fullname,drawer,close,toast,load}=ctx;
 const c={tab:'home',step:0,pet:0,service:0,master:0,date:'',time:'',edit:null,filter:'all',month:0};
 const myPets=()=>(state.data.pets||[]).filter(p=>p.owner_id===state.userId);
 const myBooks=()=>(state.data.book||[]).filter(b=>b.client_id===state.userId||myPets().some(p=>p.pet_id===b.pet_id));
 const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Moscow'});
 const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',weekday:'short'});
 const masters=()=>(state.data.masters||state.data.users||[]).filter(u=>['master','employee','groomer'].includes(u.role)).filter(u=>config.mode==='demo'||!Array.isArray(service().masters)||service().masters.some(m=>m.user_id===u.user_id));
 const pet=()=>find('pets',c.pet),service=()=>find('services',c.service);
 const getServices=()=>state.data.services.filter(s=>!s.breed_id||s.breed_id===pet().breed_id);
 function route(tab){c.tab=tab;render()}
 function render(){
  const me=find('users',state.userId),next=myBooks().filter(b=>b.date>=today()&&b.status!=='cancelled'&&b.status!=='completed').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];
  document.querySelector('#app').innerHTML=`<div class="client-app"><header class="client-header"><a class="brand" href="?app=client">МиМиРум<small>пространство заботы</small></a><nav>${[['home','Главная'],['visits','Мои визиты'],['pets','Мои питомцы'],['care','Мой профиль']].map(([id,t])=>`<button data-c-tab="${id}" class="${c.tab===id?'active':''}">${t}</button>`).join('')}</nav><button class="client-user" data-c-tab="care"><span class="avatar">${esc(me.name?.[0]||'Г')}</span><span>${esc(me.name||'Личный кабинет')}</span></button></header><main class="client-main">${state.loading?'<div class="loading">Готовим ваше пространство…</div>':state.error?`<div class="empty"><h3>Не удалось загрузить кабинет</h3><p>${esc(state.error)}</p><button class="primary" data-c-login>Настроить вход</button></div>`:c.tab==='home'?home(next,me):c.tab==='visits'?visits():c.tab==='pets'?pets():profile(me)}</main><footer class="client-footer"><div class="brand">МиМиРум<small>красота начинается с доверия</small></div><span>${config.mode==='demo'?'Демоверсия · данные примера':'Ваш личный кабинет'}</span><a href="?app=studio">Для команды ↗</a></footer><nav class="client-mobile-nav">${[['home','grid','Главная'],['visits','calendar','Визиты'],['pets','paw','Питомцы'],['care','heart','Профиль']].map(([id,i,t])=>`<button data-c-tab="${id}" class="${c.tab===id?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav></div>`;bind();ctx.mountSupport?.();
 }
 function home(next,me){return `<section class="client-hero"><div class="client-hero-copy"><div class="eyebrow">МЕСТО, ГДЕ ВАШЕГО ПИТОМЦА ЗНАЮТ ПО ИМЕНИ</div><h1>Больше нежности.<br>Меньше <em>хлопот.</em></h1><p>Любимый уход, знакомые руки и время,<br>которое удобно именно вам.</p><button class="primary" data-c-book>Подобрать окошко ${icon('arrow')}</button><div class="hero-details"><span>${icon('clock')} Запись за пару минут</span><span>${icon('heart')} Бережно к каждому</span></div></div><div class="client-hero-image"><img src="${image(myPets()[0]||{})}" alt="Питомец МиМиРум"><div class="hero-flower">✳</div><span class="hero-caption">Для маленьких.<br>С большой любовью.</span></div></section><section class="client-welcome"><div><div class="eyebrow">ВАШ МАЛЕНЬКИЙ МИР ЗАБОТЫ</div><h2>${esc(me.name||'Добро пожаловать')}, рады вам <em>снова.</em></h2></div><span class="pill green">${myPets().length} питомца в семье</span></section><div class="client-home-grid"><section class="next-visit"><div class="section-overline">БЛИЖАЙШАЯ ВСТРЕЧА <span>${icon('calendar')}</span></div>${next?visitCard(next,true):`<h3>Найдём время<br>для <em>красоты?</em></h3><p>Выберите услугу и свободное окошко. Остальное — наша забота.</p><button class="primary" data-c-book>Записать питомца ${icon('arrow')}</button>`}</section><section class="family-panel"><div class="section-overline">ВАША СЕМЬЯ <button data-c-tab="pets">Все питомцы ↗</button></div><div class="family-pets">${myPets().map(p=>`<button data-c-pet="${p.pet_id}"><img src="${image(p)}" alt="${esc(p.name)}"><b>${esc(p.name)}</b><small>${esc(breed(p))}</small></button>`).join('')}<button class="add-family" data-c-add-pet><span>+</span><b>Новый друг</b><small>Добавить питомца</small></button></div></section></div><section class="client-services"><div class="client-section-head"><div><div class="eyebrow">С ЛЮБОВЬЮ К ДЕТАЛЯМ</div><h2>Их красота. <em>Ваше спокойствие.</em></h2></div><button class="text-btn" data-c-book>Подобрать уход ↗</button></div><div class="client-service-grid">${state.data.services.slice(0,3).map((s,i)=>`<button class="client-service-tile tone-${i}" data-c-service="${s.service_id}"><span class="service-number">0${i+1}</span><span class="service-art">${icon(['scissors','paw','heart'][i])}</span><h3>${esc(s.title)}</h3><p>${durationMinutes(s)} мин · бережный уход</p><div><b>${money(s.price)}</b><span>↗</span></div></button>`).join('')}</div></section><section class="client-care-note"><span>♡</span><div><h3>Знакомые руки. Спокойный питомец.</h3><p>В записи можно выбрать любимого мастера или ближайшее свободное время.</p></div><button class="secondary" data-c-book>Выбрать время ${icon('arrow')}</button></section>`}
 function visitCard(b,featured=false){const p=find('pets',b.pet_id),s=find('services',b.service_id),m=find('users',b.master_id),past=b.date<today()||b.status==='completed',cancelled=b.status==='cancelled';return `<article class="client-visit ${featured?'featured':''}"><div class="visit-date"><b>${new Date(b.date+'T12:00').getDate()}</b><span>${new Date(b.date+'T12:00').toLocaleDateString('ru-RU',{month:'short'})}</span></div><div class="visit-main"><div class="pet-row"><img src="${image(p)}" alt=""><div><h3>${esc(p.name||'Ваш питомец')} · ${esc(s.title)}</h3><p>${b.time.slice(0,5)}–${b.end_time?salonDateParts(b.end_time).time.slice(0,5):formatTime(minutesOf(b.time)+durationMinutes(s))} · ${esc(m.name||'Мастер уточняется')}</p></div></div><div class="visit-meta"><span class="pill ${cancelled?'':past?'':'green'}">${cancelled?'Отменено':past?'В истории':config.mode==='demo'&&b.status==='pending'?'Заявка отправлена':'Запланировано'}</span><b>${money(s.price)}</b></div>${b.comment?`<p class="visit-comment">${esc(b.comment)}</p>`:''}<div class="visit-actions">${!past&&!cancelled?`<button data-c-reschedule="${b.book_id}">Перенести</button><button data-c-cancel="${b.book_id}">Отменить</button><button data-c-ics="${b.book_id}">В календарь ↗</button>`:`<button data-c-repeat="${b.book_id}">Повторить уход ↗</button>`}</div></div></article>`}
 function visits(){const upcoming=myBooks().filter(b=>b.date>=today()&&b.status!=='completed'&&b.status!=='cancelled'),history=myBooks().filter(b=>!upcoming.includes(b));const list=c.filter==='history'?history:upcoming;return `<div class="client-section-head"><div><div class="eyebrow">ВСТРЕЧИ, КОТОРЫХ ЖДУТ</div><h1>Ваши <em>визиты.</em></h1></div><button class="primary" data-c-book>Новая запись ${icon('plus')}</button></div><div class="client-tabs"><button data-c-filter="all" class="${c.filter==='all'?'active':''}">Предстоящие <span>${upcoming.length}</span></button><button data-c-filter="history" class="${c.filter==='history'?'active':''}">История <span>${history.length}</span></button></div><div class="client-visits-list">${list.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(b=>visitCard(b)).join('')||'<div class="empty"><h3>Здесь будут ваши встречи</h3><p>Выберите уход, и мы найдём удобное время.</p><button class="primary" data-c-book>Найти окошко</button></div>'}</div>`}
 function pets(){return `<div class="client-section-head"><div><div class="eyebrow">САМЫЕ ЛЮБИМЫЕ</div><h1>Моя <em>семья.</em></h1></div><button class="primary" data-c-add-pet>Добавить питомца ${icon('plus')}</button></div><div class="client-pets-grid">${myPets().map(p=>`<article class="client-pet-profile"><img src="${image(p)}" alt="${esc(p.name)}"><div><span class="eyebrow">ПАСПОРТ ЗАБОТЫ</span><h2>${esc(p.name)}</h2><p>${esc(breed(p))}</p><dl><div><dt>День рождения</dt><dd>${p.birthday?dateLabel(p.birthday):'Добавьте дату'}</dd></div><div><dt>Визитов</dt><dd>${myBooks().filter(b=>b.pet_id===p.pet_id).length}</dd></div></dl><div class="pet-profile-actions"><button class="primary" data-c-pet-book="${p.pet_id}">Записать</button><button class="text-btn" data-c-pet="${p.pet_id}">Подробнее ↗</button></div></div></article>`).join('')}</div>`}
 function profile(me){return `<div class="client-section-head"><div><div class="eyebrow">ВСЁ О ВАС</div><h1>Личный <em>кабинет.</em></h1></div></div><div class="client-profile-grid"><section class="panel settings-card"><h2>${esc(fullname(me))}</h2><p>Здесь живут ваши питомцы и встречи с МиМиРум.</p><div class="feature-line"><span>Питомцев</span><b>${myPets().length}</b></div><div class="feature-line"><span>Всего визитов</span><b>${myBooks().length}</b></div><div class="feature-line"><span>Режим</span><span>${config.mode==='demo'?'Демонстрационный кабинет':'Личный кабинет'}</span></div>${config.mode==='live'?'<button class="primary" data-c-profile>Изменить профиль и привязать Telegram</button>':''}<button class="secondary" data-c-login style="margin-top:24px">${config.mode==='demo'?'Войти в свой аккаунт':'Мой аккаунт'} ${icon('arrow')}</button></section><section class="profile-story"><span>✳</span><h2>Мы рядом.<br>В каждой <em>заботе.</em></h2><p>В разделе «Мои визиты» можно проверить статус или отменить встречу. Пожелания к уходу передайте мастеру при записи.</p><a href="https://mimi-room.ru" target="_blank" rel="noopener">Сайт студии ↗</a></section></div>`}
 function start(preset={}){
  if(config.mode==='live'&&preset.edit){drawer('Перенос визита',`<div class="notice">Для переноса свяжитесь с администратором. Пока можно оформить новую запись на другое время и отдельно отменить прежнюю.</div>`);return;}
  Object.assign(c,{step:0,pet:myPets()[0]?.pet_id||0,service:state.data.services[0]?.service_id||0,master:0,date:today(),time:'',edit:null,month:0,comment:'',assignedMaster:0,liveSlots:[],slotKey:'',slotLoading:false,slotError:'',submitError:'',submitting:false},preset);
  if(!getServices().some(s=>s.service_id===c.service))c.service=getServices()[0]?.service_id||0;
  wizard();
 }
 function rangeStart(){const d=new Date(today()+'T12:00');d.setDate(d.getDate()+c.month*14);return d.toLocaleDateString('sv-SE');}
 function rangeEnd(){const d=new Date(rangeStart()+'T12:00');d.setDate(d.getDate()+13);return d.toLocaleDateString('sv-SE');}
 function requestLiveSlots(){
  if(config.mode!=='live'||!c.service)return;
  const key=JSON.stringify([c.pet,c.service,c.master,c.month]);if(key===c.slotKey)return;
  c.slotKey=key;c.slotLoading=true;c.slotError='';c.liveSlots=[];
  api.availableSlots({pet_id:c.pet||undefined,service_id:c.service,master_id:c.master||undefined,date_from:rangeStart(),date_to:rangeEnd()}).then(slots=>{
   if(c.slotKey!==key)return;c.liveSlots=slots.filter(slot=>slot.service_id===c.service&&(!c.master||slot.master_id===c.master));c.slotLoading=false;if(c.step===2&&document.querySelector('.client-booking'))wizard();
  }).catch(error=>{if(c.slotKey!==key)return;c.slotLoading=false;c.slotError=error.message;if(c.step===2&&document.querySelector('.client-booking'))wizard();});
 }
 function choicesForDate(date){if(config.mode==='live')return (c.liveSlots||[]).filter(x=>x.date===date&&Date.parse(x.start_time)>Date.now()).map(x=>({...x,time:x.time.slice(0,5),master:x.master_id})).sort((a,b)=>a.time.localeCompare(b.time)||a.master-b.master);const svc=service();let choices=[];for(const m of masters().filter(m=>!c.master||m.user_id===c.master)){for(const t of availableSlots({bookings:state.data.book,services:state.data.services,date,masterId:m.user_id,petId:c.pet,duration:durationMinutes(svc),excludeId:c.edit})){const now=new Date().toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit',hour12:false});if(date>today()||date===today()&&t>now)choices.push({time:t,master:m.user_id})}}return choices.sort((a,b)=>a.time.localeCompare(b.time)||a.master-b.master)}
 function wizard(){
 if(c.step===2)requestLiveSlots();
 const labels=['Питомец и уход','Мастер','Свободное время','Подтверждение'];
 const svc=service();let body='';
 if(c.step===0)body=`<h3 class="booking-step-title">Для кого сегодня забота?</h3><div class="wizard-pets">${myPets().map(p=>`<button class="${c.pet===p.pet_id?'chosen':''}" data-w-pet="${p.pet_id}"><img src="${image(p)}" alt=""><b>${esc(p.name)}</b><small>${esc(breed(p))}</small></button>`).join('')}<button data-w-add-pet class="wizard-add-pet">+<small>Новый питомец</small></button></div><h3 class="booking-step-title">Выберите уход</h3><div class="wizard-options">${getServices().map(s=>`<button class="${c.service===s.service_id?'chosen':''}" data-w-service="${s.service_id}"><span class="option-radio"></span><div><b>${esc(s.title)}</b><small>${durationMinutes(s)} минут</small></div><strong>${money(s.price)}</strong></button>`).join('')}</div>`;
 if(c.step===1)body=`<h3 class="booking-step-title">Кому доверим красоту?</h3><p class="sub">Выберите знакомого мастера или найдём ближайшее окно у команды.</p><div class="wizard-options master-options"><button class="${!c.master?'chosen':''}" data-w-master="0"><span class="avatar">♡</span><div><b>Любой свободный мастер</b><small>Больше вариантов времени</small></div><span class="option-radio"></span></button>${masters().map(m=>`<button class="${c.master===m.user_id?'chosen':''}" data-w-master="${m.user_id}"><span class="avatar">${esc(m.name[0])}${esc(m.surname[0])}</span><div><b>${esc(fullname(m))}</b><small>Грумер МиМиРум</small></div><span class="option-radio"></span></button>`).join('')}</div>`;
 if(c.step===2){
  const dates=Array.from({length:14},(_,i)=>{const d=new Date(rangeStart()+'T12:00');d.setDate(d.getDate()+i);return d.toLocaleDateString('sv-SE')});
  const unique=[...new Set(choicesForDate(c.date).map(x=>x.time))];
  body=`<h3 class="booking-step-title">Найдём ваше окошко.</h3><div class="booking-period"><button data-w-period="-1" ${!c.month?'disabled':''} aria-label="Предыдущие даты">‹</button><span>${dateLabel(dates[0])} — ${dateLabel(dates.at(-1))}</span><button data-w-period="1" aria-label="Следующие даты">›</button></div><div class="booking-date-grid">${dates.map(d=>`<button data-w-date="${d}" class="${c.date===d?'chosen':''}"><span>${new Date(d+'T12:00').toLocaleDateString('ru-RU',{weekday:'short'})}</span><b>${new Date(d+'T12:00').getDate()}</b><i class="${choicesForDate(d).length?'has-slots':''}"></i></button>`).join('')}</div><div class="slot-legend"><span>● Есть свободные окна</span><span>${dateLabel(c.date)}</span></div>`;
  if(c.slotLoading)body+='<div class="loading" role="status">Подбираем свободное время…</div>';
  else if(c.slotError)body+=`<div class="notice" role="alert">${esc(c.slotError)}</div><button class="secondary" id="w-retry">Попробовать снова</button>`;
  else if(unique.length)body+=['Утро','День','Вечер'].map((label,index)=>{const times=unique.filter(t=>index===0?minutesOf(t)<720:index===1?minutesOf(t)>=720&&minutesOf(t)<1020:minutesOf(t)>=1020);return times.length?`<div class="slot-group"><h4>${label}</h4><div>${times.map(t=>`<button data-w-time="${t}" class="${c.time===t?'chosen':''}"><b>${t}</b><small>${durationMinutes(svc)} мин</small></button>`).join('')}</div></div>`:''}).join('');
  else body+='<div class="empty compact"><h3>На этот день окошек нет.</h3><p>Выберите другую дату или мастера.</p><button class="secondary" id="w-nearest">Найти ближайшее окно ↗</button></div>';
  body+=`<p class="sub">${c.master?'Выбран '+esc(fullname(find('users',c.master))):'Подбираем свободное время у мастеров студии.'}</p>`;
 }
 if(c.step===3){const selected=choicesForDate(c.date).find(x=>x.time===c.time),m=find('users',c.assignedMaster||selected?.master);body=`<div class="booking-review"><img src="${image(pet())}" alt=""><div><span class="eyebrow">ПОЧТИ ГОТОВО</span><h3>${esc(pet().name)} идёт за красотой.</h3><p>${esc(breed(pet()))}</p></div></div><div class="review-rows"><div><span>Уход</span><b>${esc(svc.title)}</b></div><div><span>Когда</span><b>${dateLabel(c.date)} · ${c.time}</b></div><div><span>Мастер</span><b>${esc(fullname(m))}</b></div><div><span>Продолжительность</span><b>${durationMinutes(svc)} минут</b></div><div><span>Стоимость</span><strong>${money(svc.price)}</strong></div></div><label class="field">Пожелания мастеру<textarea id="w-comment" placeholder="Особенности кожи, привычки, пожелания к стрижке…">${esc(c.comment||'')}</textarea></label><label class="booking-consent"><input type="checkbox" id="w-consent"> Проверил(а) дату, время и стоимость ухода</label>`}
 drawer(c.edit?'Перенос визита':'Запись с заботой',`<div class="client-booking"><div class="wizard-progress">${labels.map((s,i)=>`<span class="${c.step===i?'current':c.step>i?'complete':''}"><i>${c.step>i?'✓':i+1}</i>${s}</span>`).join('')}</div>${body}<div class="error" id="w-error" role="alert">${esc(c.submitError||'')}</div><div class="wizard-bottom"><button class="secondary" id="w-back">${c.step?'Назад':'Закрыть'}</button><span>${c.step>0?money(svc.price):'Бережный уход'}</span><button class="primary" id="w-next">${c.step===3?'Подтвердить запись':'Далее'} ${icon('arrow')}</button></div><p class="wizard-demo-note">${config.mode==='demo'?'Демозапись · данные сохраняются в этом браузере':'Запись появится в кабинете после успешного сохранения.'}</p></div>`);
 document.querySelector('.drawer').classList.add('booking-drawer');
 document.querySelectorAll('[data-w-pet]').forEach(el=>el.onclick=()=>{c.pet=Number(el.dataset.wPet);if(!getServices().some(s=>s.service_id===c.service))c.service=getServices()[0]?.service_id||0;c.time='';wizard()});
 document.querySelectorAll('[data-w-service]').forEach(el=>el.onclick=()=>{c.service=Number(el.dataset.wService);c.time='';wizard()});
 document.querySelectorAll('[data-w-master]').forEach(el=>el.onclick=()=>{c.master=Number(el.dataset.wMaster);c.time='';wizard()});
 document.querySelectorAll('[data-w-date]').forEach(el=>el.onclick=()=>{c.date=el.dataset.wDate;c.time='';wizard()});
 document.querySelectorAll('[data-w-time]').forEach(el=>el.onclick=()=>{c.time=el.dataset.wTime;c.assignedMaster=choicesForDate(c.date).find(x=>x.time===c.time)?.master;wizard()});
 document.querySelectorAll('[data-w-period]').forEach(el=>el.onclick=()=>{c.month=Math.max(0,c.month+Number(el.dataset.wPeriod));const d=new Date(today()+'T12:00');d.setDate(d.getDate()+c.month*14);c.date=d.toLocaleDateString('sv-SE');c.time='';wizard()});
 document.querySelector('[data-w-add-pet]')?.addEventListener('click',()=>addPet(true));
 document.querySelector('#w-retry')?.addEventListener('click',()=>{c.slotKey='';wizard()});
 document.querySelector('#w-nearest')?.addEventListener('click',()=>{if(config.mode==='live'){const slot=(c.liveSlots||[]).find(x=>Date.parse(x.start_time)>Date.now());if(slot){c.date=slot.date;c.time='';wizard()}else{c.month++;c.date=rangeStart();c.slotKey='';wizard()}return;}for(let i=0;i<60;i++){const d=new Date(today()+'T12:00');d.setDate(d.getDate()+i);const date=d.toLocaleDateString('sv-SE');if(choicesForDate(date).length){c.date=date;c.month=Math.floor(i/14);c.time='';wizard();return}}toast('За 60 дней свободных окон не найдено')});
 document.querySelector('#w-back').onclick=()=>{if(c.step===3)c.comment=document.querySelector('#w-comment').value;if(c.step){c.step--;wizard()}else close()};
 document.querySelector('#w-next').onclick=async()=>{
  if(c.submitting)return;
  if(c.step===0&&(!c.pet||!c.service)){document.querySelector('#w-error').textContent='Выберите питомца и услугу.';return;}
  if(c.step===2&&(!c.time||c.slotLoading||c.slotError)){document.querySelector('#w-error').textContent='Нажмите на доступное окошко времени.';return;}
  if(c.step<3){c.submitError='';c.step++;wizard();return;}
  if(!document.querySelector('#w-consent').checked){document.querySelector('#w-error').textContent='Подтвердите, что проверили детали записи.';return;}
  const btn=document.querySelector('#w-next');btn.disabled=true;c.submitting=true;c.comment=document.querySelector('#w-comment').value;
  try{
   const selected=choicesForDate(c.date).find(x=>x.time===c.time&&x.master===c.assignedMaster);
   if(!selected)throw Error('Окошко уже недоступно. Вернитесь к выбору времени.');
   const data={pet_id:c.pet,service_id:c.service,master_id:selected.master,comment:c.comment,...(config.mode==='live'?{start_time:selected.start_time,client_id:state.userId}:{date:c.date,time:c.time+':00',status:'pending'})};
   const booking=await api.save('book',data,c.edit);c.submitting=false;close();await load();success(booking);
  }catch(error){c.submitting=false;if(error.status===409){c.step=2;c.time='';c.slotKey='';c.submitError='Это окошко только что заняли. Выберите другое время.';wizard();}else{document.querySelector('#w-error').textContent=error.message;btn.disabled=false;}}
 };
 }
 function success(b){drawer('До скорой встречи!',`<div class="booking-success"><span>✓</span><div class="eyebrow">ВАША ЗАЯВКА СОХРАНЕНА</div><h2>${esc(find('pets',b.pet_id).name)},<br>будем <em>ждать.</em></h2><p>${dateLabel(b.date)} в ${b.time.slice(0,5)}<br>${esc(find('services',b.service_id).title)}</p><button class="primary" id="success-visits">Мои визиты ${icon('arrow')}</button><button class="secondary" id="success-calendar">Добавить в календарь</button><small>${config.mode==='demo'?'Деморежим: подтверждение администратором доступно в пространстве команды.':b.status==='confirmed'?'Визит подтверждён студией.':'Следите за статусом в разделе «Мои визиты».'}</small></div>`);document.querySelector('#success-visits').onclick=()=>{close();route('visits')};document.querySelector('#success-calendar').onclick=()=>calendarFile(b)}
 function addPet(returnToBooking=false){drawer('Знакомимся с вашим другом',`<form id="client-pet-form"><label class="field">Кличка<input name="name" required maxlength="80" placeholder="Как зовут вашего друга?"></label><label class="field">Порода<select name="breed_id"><option value="">Не указана</option>${state.data.breeds.map(b=>`<option value="${b.breed_id}">${esc(b.title)}</option>`).join('')}</select></label><label class="field">День рождения<input name="birthday" type="date" max="${today()}"></label><div id="pet-error" class="error"></div><button class="primary" type="submit">Добавить в семью ♡</button></form>`);document.querySelector('#client-pet-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.owner_id=state.userId;data.breed_id=Number(data.breed_id)||null;data.birthday=data.birthday||null;try{const p=await api.save('pets',data);close();await load();if(returnToBooking){c.pet=p.pet_id;c.step=0;wizard()}else route('pets');toast('Новый друг в вашей семье ♡')}catch(err){document.querySelector('#pet-error').textContent=err.message}}}
 function showPet(id){const p=find('pets',Number(id));if(!myPets().includes(p))return;drawer('Паспорт заботы',`<div class="detail-hero"><img src="${image(p)}" alt=""><div><h3>${esc(p.name)}</h3><p>${esc(breed(p))}</p></div></div><div class="detail-list"><div><span>День рождения</span><b>${p.birthday?dateLabel(p.birthday):'Не указан'}</b></div></div><h3 class="section-title">История ухода</h3><button class="secondary" id="pet-full-history">Открыть полную историю</button>${myBooks().filter(b=>b.pet_id===p.pet_id).map(b=>`<div class="request"><b>${esc(find('services',b.service_id).title)}</b><p class="sub">${dateLabel(b.date)} · ${b.time.slice(0,5)}</p></div>`).join('')||'<p class="sub">Первое знакомство впереди.</p>'}<button class="primary" id="pet-book-now" style="margin-top:24px">Выбрать окошко</button>`);document.querySelector('#pet-book-now').onclick=()=>start({pet:p.pet_id});document.querySelector('#pet-full-history').onclick=()=>ctx.history(p)}
 function cancel(id){const b=myBooks().find(x=>x.book_id===Number(id));if(!b)return;drawer('Отменить визит?',`<p class="sub">${esc(find('pets',b.pet_id).name)} · ${dateLabel(b.date)} · ${b.time.slice(0,5)}</p><div class="notice">Время освободится для других гостей. История визита сохранится в кабинете.</div><div class="form-actions"><button class="secondary" id="keep-visit">Оставить запись</button><button class="primary" id="cancel-visit">Отменить визит</button></div>`);document.querySelector('#keep-visit').onclick=close;document.querySelector('#cancel-visit').onclick=async()=>{try{await api.cancelBooking(b.book_id);close();await load();route('visits');toast('Визит отменён')}catch(e){toast(e.message)}}}
 function calendarFile(b){const end=minutesOf(b.time)+durationMinutes(find('services',b.service_id));const stamp=t=>b.date.replaceAll('-','')+'T'+t.replaceAll(':','').slice(0,4)+'00';const escapeICS=s=>String(s).replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//MiMiRoom//Care//RU','BEGIN:VEVENT',`UID:mimiroom-${b.book_id}@mimi-room.ru`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;TZID=Europe/Moscow:${stamp(b.time)}`,`DTEND;TZID=Europe/Moscow:${stamp(formatTime(end))}`,`SUMMARY:${escapeICS('МиМиРум · '+find('pets',b.pet_id).name+' · '+find('services',b.service_id).title)}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'}));a.download='MiMiRoom_visit.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
 function bind(){document.querySelectorAll('[data-c-tab]').forEach(e=>e.onclick=()=>route(e.dataset.cTab));document.querySelectorAll('[data-c-book]').forEach(e=>e.onclick=()=>start());document.querySelectorAll('[data-c-service]').forEach(e=>e.onclick=()=>start({service:Number(e.dataset.cService)}));document.querySelectorAll('[data-c-pet-book]').forEach(e=>e.onclick=()=>start({pet:Number(e.dataset.cPetBook)}));document.querySelectorAll('[data-c-pet]').forEach(e=>e.onclick=()=>showPet(e.dataset.cPet));document.querySelectorAll('[data-c-add-pet]').forEach(e=>e.onclick=()=>addPet());document.querySelectorAll('[data-c-filter]').forEach(e=>e.onclick=()=>{c.filter=e.dataset.cFilter;render()});document.querySelectorAll('[data-c-reschedule]').forEach(e=>e.onclick=()=>{const b=myBooks().find(b=>b.book_id===Number(e.dataset.cReschedule));start({pet:b.pet_id,service:b.service_id,master:b.master_id,date:b.date,edit:b.book_id,comment:b.comment})});document.querySelectorAll('[data-c-repeat]').forEach(e=>e.onclick=()=>{const b=myBooks().find(b=>b.book_id===Number(e.dataset.cRepeat));start({pet:b.pet_id,service:b.service_id,master:b.master_id})});document.querySelectorAll('[data-c-cancel]').forEach(e=>e.onclick=()=>cancel(e.dataset.cCancel));document.querySelectorAll('[data-c-ics]').forEach(e=>e.onclick=()=>calendarFile(myBooks().find(b=>b.book_id===Number(e.dataset.cIcs))));document.querySelectorAll('[data-c-profile]').forEach(e=>e.onclick=()=>ctx.profile());document.querySelectorAll('[data-c-login]').forEach(e=>e.onclick=()=>ctx.login())}
 return {render,start};
}
